raw:
{
  "spells": [
    {
      "id": "spell_fire_01",
      "theory": "火星术把一点魔力压进干火绒的纤维缝隙，摩擦出肉眼可见的红色火星。只有彻底干燥且松散的植物纤维能留住这点热量，湿柴的水膜会立刻吸走火星，活物体内的水分同样会使法术失效。火星只持续到引燃火绒为止，不会自行蔓延到其他燃料。",
      "casting": "拇指与食指捏住一撮火绒，另一只手在绒团上方快速画一个向下的短竖，同时把魔力聚到指尖。竖线歪斜时须重新画。",
      "failure": "火绒只冒出一缕青烟，随后焦黑卷曲却不出现火苗。若魔力送得太急，火星会炸成几粒碎点落在手背，留下针尖大的红痕，痛感持续片刻。",
      "counters": [
        "朝火绒撒一把细沙，沙粒隔开纤维与魔力，火星无法附着。",
        "用湿布盖住火绒，水汽渗入纤维后法术自然失效。"
      ],
      "socialConsequences": "在河谷乡约见证的民事承诺中，新人常用火星术点燃合婚火绒，象征两家灶火合并。城中公会许可的野炊点也允许施放，但若在仓库附近使用，守夜人会要求先搬开干草。纵火烧伤他人或引燃他人财物，无论是否故意，都按纵火伤人另算重罪。",
      "law": {
        "river": "public",
        "city": "permit",
        "port": "crime"
      },
      "proficiencyEffects": [
        "刚学会时火星偏小，须把火绒捻得极松才易点着。",
        "熟练后火星能稳定落在指定绒团中央，不溅到手指。",
        "精熟者可在微风中画竖，火星仍不偏离火绒。",
        "极高造诣下火星大小可控，但只限于点燃干火绒。"
      ]
    },
    {
      "id": "spell_fire_02",
      "theory": "暖掌术让魔力在掌心皮下缓慢循环，像搓手那样把热量均匀铺开。热量被限制在手掌表面，不会传给接触者，因此揉面时面团不会发烫，握手也不会烫伤对方。掌心的汗液会带走部分热量，法术持续期间须保持手掌干燥。",
      "casting": "双掌合拢，十指交叉，轻轻摩擦三次，然后把魔力从手腕推向掌心。摩擦停止后热量仍会保留片刻。",
      "failure": "掌心只有局部发热，其余部分依旧冰凉，揉面时面团粘手。若魔力循环过速，掌心会突然发烫，接触冷物时可能留下短暂红印，但不会起泡。",
      "counters": [
        "把双手浸入冷水，热量被水带走，暖意迅速消退。",
        "在掌心涂一层油脂，魔力循环受阻，热度无法均匀铺开。"
      ],
      "socialConsequences": "河谷的面包师常请会暖掌术的人帮忙揉面，尤其在寒冬。城中公会许可的面包坊要求施术者先洗净双手，避免汗渍污染面团。港口货栈的搬运工若用暖掌术解冻绳索，港务会检查是否因升温导致货物受潮，造成货损须赔偿。",
      "law": {
        "river": "public",
        "city": "permit",
        "port": "consent"
      },
      "proficiencyEffects": [
        "初学时掌心热度不均，揉面需频繁翻动面团。",
        "熟练后热度稳定，可连续揉完一盆面团不烫手。",
        "精熟者能按面团软硬调整掌心温度，仍不烫伤接触者。",
        "极高造诣下热量分布极匀，但温度上限不变。"
      ]
    },
    {
      "id": "spell_fire_03",
      "theory": "烘衣术把魔力化成细微的干燥气流，从衣物纤维内部把潮气逼到表面，再让气流带走水汽。染料与纤维被魔力轻轻裹住，不受干燥影响。厚棉布需要更长时间，丝绸则要放慢气流，否则会皱缩。法术只作用于一件衣物，无法同时烘干多件。",
      "casting": "双手提起衣物两肩，在胸前画一个向下的漏斗形，然后轻轻抖动三次。抖动停止后气流仍会持续片刻。",
      "failure": "衣物表面干了，内层依旧潮湿，穿在身上很快返潮。若气流过猛，染料会随水汽浮到表面，形成一圈圈浅色水渍，纤维也可能起毛。",
      "counters": [
        "把衣物重新浸入清水，潮气回归后法术失效。",
        "用厚布盖住衣物，气流无法带走水汽，干燥中断。"
      ],
      "socialConsequences": "琥珀海岸的渔民常请会烘衣术的人帮忙处理受潮的帆布，但港务规定若因烘干导致帆布缩水、影响航运安全，须追究货损责任。城中公会许可的洗衣坊要求施术者先确认衣物主人同意，避免损坏贵重织物。河谷的旅人则常在乡约见证下互相帮忙烘衣，不收取费用。",
      "law": {
        "river": "consent",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "初学时只能烘干薄布，厚衣内层仍潮。",
        "熟练后能均匀烘干一件外衣，不伤染料。",
        "精熟者可处理丝绸，纤维不皱缩。",
        "极高造诣下干燥极匀，但仍只限一件衣物。"
      ]
    }
  ]
}
